# English that EN8 replaced (their keys now read the new English above)
STALE = ['🍃 Windfall: {side} +{n} Lumber.', '🍃 Chablis : {side} +{n} Bois.','Takes half of each hit on your bramble (rounded up); the bramble takes the rest.',
         'Takes half of each hit on your bramble from an enemy in its column or the next one (rounded up); the bramble takes the rest.',
         "Hits from units only: swings, shots, skills, a boomerang. The field's own damage to a bramble isn't shared. With two or more, the one nearest the attacker's column takes it. Its share is plain damage: its Shield soaks first, Armor doesn't."]
TEXTS = os.path.join(ROOT, 'bramblewood-texts.js')
CHANGED = {'ui.sk-rampart', 'ui.sk-rampart-codex'}
ANCHOR = '  "ui.en7-trig-bleed": '
def js_str(s): return json.dumps(s, ensure_ascii=False)
def dump(path, d):
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(d, fh, ensure_ascii=False, indent=1); fh.write('\n')
ph = lambda s: sorted(set(re.findall(r'\{\w+\}', s)))

def main():
    src = open(TEXTS, encoding='utf-8').read()
    new_lines = []
    for k, row in T.items():
        assert len(row) == 13, k
        for i in range(1, 13): assert ph(row[0]) == ph(row[i]), (k, CODES[i - 1])
        line = '  %s: %s,' % (js_str(k), js_str(row[0]))
        m = re.search(r'^  "%s": .*,$' % re.escape(k), src, re.M)
        if m:
            src = src[:m.start()] + line + src[m.end():]
        else:
            new_lines.append(line)
    if new_lines:
        i = src.index(ANCHOR); j = src.index('\n', i) + 1
        src = src[:j] + '\n'.join(new_lines) + '\n' + src[j:]
    open(TEXTS, 'w', encoding='utf-8').write(src)
    for ci, code in enumerate(CODES):
        path = os.path.join(ROOT, 'lang', code + '.json'); pack = json.load(open(path, encoding='utf-8'))
        for k, row in T.items(): pack[row[0]] = row[ci + 1]
        for old in STALE: pack.pop(old, None)
        for old in [k for k in pack if k.startswith('🍃 Windfall:')]: pack.pop(old, None)
        dump(path, pack)
        upath = os.path.join(ROOT, 'lang', 'ui', code + '.json'); ui = json.load(open(upath, encoding='utf-8')) # the old bramble line is a TX key now (ui.en8-castle-regen)
        dirty = [ui.pop(k, None) for k in ('Heals {v1} ❤ each round', 'When played, the enemy facing it loses {v1} Attack.')]
        if any(x is not None for x in dirty): dump(upath, ui)
        cpath = os.path.join(ROOT, 'lang', 'cards', code + '.json'); cpack = json.load(open(cpath, encoding='utf-8'))
        for en, row in NAMES.items(): cpack[en] = row[ci]
        dump(cpath, cpack)
    print('EN8 texts: %d keys (%d new), %d packs' % (len(T), len(new_lines), len(CODES)))

if __name__ == '__main__': main()
